import{z as o,x as p,o as i,c as d,q as r,j as A,D as e,d as E,s,S as t,b as l}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"Diffie–Hellman","description":"","frontmatter":{"title":"Diffie–Hellman","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/diffie-hellman-paper.md","filePath":"cs/diffie-hellman-paper.md","lastUpdated":1791413859000}'),B={name:"cs/diffie-hellman-paper.md"};function f(m,a,h,D,c,b){const n=p("Mermaid");return i(),d("div",null,[a[2]||(a[2]=r('<h1 id="diffie–hellman" tabindex="-1">Diffie–Hellman <a class="header-anchor" href="#diffie–hellman" aria-label="Permalink to &quot;Diffie–Hellman&quot;">​</a></h1><div class="epigraph"><p>公开两指数运算，使没有预共享秘密的双方得到共同密钥；认证仍要另做，否则中间人各握一钥。</p><footer>—— Diffie and Hellman, New Directions in Cryptography, IEEE Trans. Info. Theory 1976</footer></div><p><a href="/cs/gray-transactions">上一课</a>附录对照了关系模型原文。附录对照，不插入主干。主干已在<a href="/cs/pubkey-envelope">公钥与信封</a>、<a href="/cs/tls-handshake">TLS 握手</a>、<a href="/cs/mitm">中间人</a>里用过密钥协商与假冒几何；这里对照 <strong>1976 原文的问题</strong>：公钥方向——加密与认证能否不先送对称钥，陷门单向函数作为设想。不重做离散对数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Shannon 1949 保密论默认共享密钥。主干对称课停在 AEAD。Diffie–Hellman 的缺口是公开密钥学：公钥可公布，DH 交换得到共同秘密，数字签名使认证可不共享 MAC 键。RSA 同年稍后另文；本附录只钉 1976 的方向，不把分解模数插进来当证明。</p><p><span class="marginnote">原文已警告未认证交换的假冒。主干中间人课取的就是这一警告。Goldwasser–Micali 语义安全是后续命名，主干已用名字，不伪造论文页码。</span></p><p><span class="marginnote">常见误区：以为「协商出密钥」就等于「密钥是对端的」。DH 只保证两人共享了同一个数，不保证对面是谁——中间人可以左边谈一个、右边再谈一个，把两条隧道各自解密再转发。所以 1976 原文就点名：认证要另做。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>公开素数与生成元；各方选指数，交换 \\(g^a\\)、\\(g^b\\)，共享 \\(g^{ab}\\)。前向保密来自临时指数，是后来工程对这篇的用法（TLS 1.3 ECDHE），不是 1976 的 TLS。签名与公钥加密在原文是同一方向的另两块。</p><p><span class="marginnote">数字实例（仅为演示，真实参数是几百位的数）：取 \\(p=23\\)、\\(g=5\\)。Alice 选 \\(a=6\\)，发 \\(5^6\\bmod 23=8\\)；Bob 选 \\(b=15\\)，发 \\(5^{15}\\bmod 23=19\\)。Alice 算 \\(19^6\\bmod 23=2\\)，Bob 算 \\(8^{15}\\bmod 23=2\\)——两人得到同一个 \\(2\\)，旁观者全程只看见 \\(8\\) 和 \\(19\\)。</span></p>',10)),(i(),A(t,null,{default:e(()=>[s(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20DH%5B%22%E5%85%AC%E5%BC%80%E6%8C%87%E6%95%B0%E4%BA%A4%E6%8D%A2%22%5D%20--%3E%20K%5B%22%E5%85%B1%E5%90%8C%E5%AF%86%E9%92%A5%22%5D%0A%20%20K%20--%3E%20SYM%5B%22%E5%AF%B9%E7%A7%B0%20AEAD%22%5D%0A%20%20AUTH%5B%22%E8%AE%A4%E8%AF%81%E5%8F%A6%E5%81%9A%22%5D%20--%3E%20MITM%5B%22%E5%90%A6%E5%88%99%E4%B8%A4%E6%9D%A1%E4%BC%9A%E8%AF%9D%22%5D%0A%20%20K%20--%3E%20TRUNK%5B%22%E4%B8%BB%E5%B9%B2%3A%20%E4%BF%A1%E5%B0%81%20%2F%20TLS%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[E("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,"计算假设（离散对数难）把「看见报文」与「得到 \\(k\\)」切开，服务威胁模型里的被动者。主动者要证书或预共享，主干 PKI 课已接。量子算法对 DH 的冲击是后话，主干不插入替换课。",-1)),a[5]||(a[5]=l("p",null,"上一张图画 DH 在整个安全课序里的位置；这张拆开一次交换的时序：每一步谁发出什么、双方最后在哪一步得到同一个数。",-1)),(i(),A(t,null,{default:e(()=>[s(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20PUB%5B%22%E5%85%88%E5%85%AC%E5%BC%80%20g%20%E4%B8%8E%20p%22%5D%20--%3E%20A%5B%22Alice%20%E9%80%89%E7%A7%98%E5%AF%86%20a%20%E5%8F%91%E9%80%81%20g%20%E7%9A%84%20a%20%E6%AC%A1%E6%96%B9%22%5D%0A%20%20PUB%20--%3E%20B%5B%22Bob%20%E9%80%89%E7%A7%98%E5%AF%86%20b%20%E5%8F%91%E9%80%81%20g%20%E7%9A%84%20b%20%E6%AC%A1%E6%96%B9%22%5D%0A%20%20A%20--%3E%20AK%5B%22Alice%20%E7%94%A8%E6%94%B6%E5%88%B0%E7%9A%84%E6%95%B0%E8%87%AA%E4%B9%98%20a%20%E6%AC%A1%22%5D%0A%20%20B%20--%3E%20BK%5B%22Bob%20%E7%94%A8%E6%94%B6%E5%88%B0%E7%9A%84%E6%95%B0%E8%87%AA%E4%B9%98%20b%20%E6%AC%A1%22%5D%0A%20%20AK%20--%3E%20SAME%5B%22%E4%B8%A4%E4%BA%BA%E5%BE%97%E5%88%B0%E5%90%8C%E4%B8%80%E4%B8%AA%20g%20%E7%9A%84%20ab%20%E6%AC%A1%E6%96%B9%22%5D%0A%20%20BK%20--%3E%20SAME%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">术语翻译：「单向函数」就是正着算容易、反着算没辙的函数——由 \\(g\\) 和 \\(a\\) 算 \\(g^a\\bmod p\\) 很快，但从 \\(g^a\\) 反推 \\(a\\)（离散对数）在合适的素数下实际不可行。DH 的安全性全部押在这条不对称上。</span></p><h3 id="为何对照而不插入主干" tabindex="-1">为何对照而不插入主干 <a class="header-anchor" href="#为何对照而不插入主干" aria-label="Permalink to &quot;为何对照而不插入主干&quot;">​</a></h3><p>安全课从 CIA 与威胁模型进入，先对称后公钥，因为会话数据走对称。把 1976 插在 CIA 之前，读者会以为安全等于公钥。附录只对照方向的出处。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 1976 与 Merkle 密钥分配、与 RSA 专利史写成一课。下一篇对照 Patterson/Hennessy 如何把体系结构收成量化教材，那是流水线与 Cache 主干的文献。</p><p>认证加密与 DH 是不同层：DH 给共享秘密，AEAD 用它保护字节。主干已按这个顺序上课。</p><p>对照结束应回到主干<a href="/cs/pubkey-envelope">公钥与信封</a>与<a href="/cs/mitm">中间人</a>。1976 文不插入 CIA 之前。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Diffie–Hellman 1976：公开密钥方向与 DH 共享秘密。</li><li>主干信封、TLS、中间人课已取用；认证不是 DH 自动附赠。</li><li>不插入 CIA 课之前。</li><li>出处：Diffie and Hellman, <em>IEEE TIT</em> 22(6), 1976。</li></ul>',9))])}const C=o(B,[["render",f]]);export{T as __pageData,C as default};
